"""Generate deterministic, independently calculated Q2.30 biquad test vectors."""

from __future__ import annotations

import argparse
from pathlib import Path
import random

SCALE = 1 << 30
SIGNAL_MIN = -(1 << 23)
SIGNAL_MAX = (1 << 23) - 1
COEFFICIENT_MIN = -(1 << 31)
COEFFICIENT_MAX = (1 << 31) - 1

# Q2.30 coefficients generated by scripts/fixed_point_model.py for 32 kHz,
# 300 Hz high-pass followed by 6 kHz low-pass.
REAL_SOS = (
    (1029936539, -2059873079, 1029936539, -2058085217, 987919117),
    (200461514, 400923028, 200461514, -497075920, 225180151),
)


def expected_output(samples: tuple[int, ...], coefficients: tuple[int, ...]) -> int:
    x0, x1, x2, y1, y2 = samples
    b0, b1, b2, a1, a2 = coefficients
    accumulator = b0 * x0 + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
    # Python's // rounds negative values downward; explicitly truncate to zero.
    reduced = accumulator // SCALE if accumulator >= 0 else -((-accumulator) // SCALE)
    return max(SIGNAL_MIN, min(SIGNAL_MAX, reduced))


def generate(seed: int, random_cases: int) -> list[tuple[int, ...]]:
    zero = (0, 0, 0, 0, 0)
    unity = (SCALE, 0, 0, 0, 0)
    cases: list[tuple[tuple[int, ...], tuple[int, ...]]] = [
        (zero, zero),
        ((123, 0, 0, 0, 0), unity),
        ((-123, 0, 0, 0, 0), unity),
        ((1, 0, 0, 0, 0), (SCALE // 2, 0, 0, 0, 0)),
        ((-3, 0, 0, 0, 0), (SCALE // 2, 0, 0, 0, 0)),
        ((-3, 0, 0, 0, 0), (SCALE // 2 + 1, 0, 0, 0, 0)),
        ((SIGNAL_MAX, SIGNAL_MAX, 0, 0, 0), (SCALE, SCALE, 0, 0, 0)),
        ((SIGNAL_MIN, SIGNAL_MIN, 0, 0, 0), (SCALE, SCALE, 0, 0, 0)),
        ((0, 0, 0, 73, 0), (0, 0, 0, -SCALE, 0)),
        ((0, 0, 0, 0, -73), (0, 0, 0, 0, -SCALE)),
        ((12000, -300, 25, -100, 10), REAL_SOS[0]),
        ((-15000, 600, -30, 55, -20), REAL_SOS[1]),
    ]
    rng = random.Random(seed)
    for index in range(random_cases):
        samples = tuple(rng.randint(SIGNAL_MIN, SIGNAL_MAX) for _ in range(5))
        if index % 3 == 0:
            coefficients = REAL_SOS[index % 2]
        elif index % 3 == 1:
            coefficients = tuple(rng.randint(COEFFICIENT_MIN, COEFFICIENT_MAX) for _ in range(5))
        else:
            coefficients = tuple(rng.randint(-2 * SCALE, 2 * SCALE - 1) for _ in range(5))
        cases.append((samples, coefficients))
    return [(*samples, *coefficients, expected_output(samples, coefficients))
            for samples, coefficients in cases]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--seed", type=int, default=20261101)
    parser.add_argument("--random-cases", type=int, default=1000)
    parser.add_argument("--output", type=Path, default=Path("/tmp/neurosig-biquad-vectors.txt"))
    args = parser.parse_args()
    if args.random_cases < 0:
        parser.error("--random-cases must be nonnegative")
    vectors = generate(args.seed, args.random_cases)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("".join(" ".join(str(value) for value in row) + "\n" for row in vectors))
    print(f"Wrote {len(vectors)} vectors with seed {args.seed} to {args.output}")


if __name__ == "__main__":
    main()
